import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-my-inspection-dashboard',
  templateUrl: './my-inspection-dashboard.page.html',
  styleUrls: ['./my-inspection-dashboard.page.scss'],
})
export class MyInspectionDashboardPage implements OnInit {

  form: FormGroup;
  userid: any;
  trainerData: any;
  dataServe: boolean;
  pipe = new DatePipe('en-US');
  todayDateFormat: string;
  noData: boolean;

  constructor(
    private router: Router,
    private fb: FormBuilder,
        private utilityService: UserService,
        private userSessionService: UserSessionService,
        private alertService: AlertService) { }

  ngOnInit() {
    this.initialValidator()
  }


  ionViewDidEnter() {
    this.todayDateFormat = this.pipe.transform(new Date(), 'yyyy-MM-dd');
    this.userid = this.userSessionService.emis_username();
    this.form.controls.date.setValue(this.todayDateFormat);
    if(this.form.value.date) {
      this.onSave();
    }
}

  initialValidator() {
    this.form = this.fb.group({
        user_id: new FormControl(this.userid),
        date: new FormControl('', Validators.required),
    });
}

  goToBack() {
    this.router.navigate(['/tabs/inspectionEnnumezhuthum'])
}

  goToMenuData(id) {
    this.router.navigate(['/tabs/inspectionquestion'], { queryParams: { "id": id } });
  }

  onSave() {
    this.utilityService.getTrainer(this.userid,this.form.value.date).subscribe((response) => {
      if(response.dataStatus) {
        this.noData =false;
        this.trainerData = []
        this.trainerData = response.result;
        if(this.trainerData){
          this.dataServe = true
        }
      } else {
        this.noData =true;
      }
      
  }); 
  }

  view(id,date,time) {
    debugger
    this.router.navigate(['/tabs/writing-inspection'], { queryParams: { "page":1,"id": id , "userid": this.userid,
  "date": date,'time':time} });
  }

  onClickFuntion(event) {
    debugger
    console.log(event)
  }

}
